def parse_all(self, intervals):
    if isinstance(intervals, (str, bytes)) or not hasattr(intervals, "__iter__"):
        raise ValueError("expected a sequence of intervals")
    out = []
    for item in intervals:
        iv = self.parse(item)
        if not self.is_empty(*iv):
            out.append(iv)
    return out

