def merge(self, ivs):
    out = []
    for lo, hi, lc, hc in self.sort(ivs):
        if out:
            plo, phi, plc, phc = out[-1]
            if phi > lo or (phi == lo and self.touching_merges(phc, lc)):
                if hi > phi:
                    phi, phc = hi, hc
                elif hi == phi:
                    phc = phc or hc
                if lo == plo:
                    plc = plc or lc
                out[-1] = (plo, phi, plc, phc)
                continue
        out.append((lo, hi, lc, hc))
    return out

